entries.commands:
# ===== rsync 断点续传同步大文件（先 -n 演练）=====
# ---- 0. ★ 首次务必 -n 演练（dry run）：确认将同步/覆盖的清单再实跑 ----
rsync -avn --progress {{src_path}} {{dst_path}}
# ---- 1. 实跑（-P = --partial --progress；中断后重跑同一条命令即断点续传）----
rsync -avP {{src_path}} {{dst_path}}
# ---- 2. 校验（单文件全量比对；目录用 du -sh 两侧对比先粗验）----
sha256sum {{src_path}}
sha256sum {{dst_path}}

# ===== scp 限速传输 =====
# ---- scp：-l 单位 Kbit/s（8000 ≈ 1 MB/s），给管理口留出带宽数量级 ----
scp -l 8000 {{src_path}} {{remote_user}}@{{remote_ip}}:{{dst_path}}
# ---- 备选：rsync --bwlimit 单位 KB/s（断点续传、目录递归更省心，二选一）----
rsync -avP --bwlimit=8000 {{src_path}} {{remote_user}}@{{remote_ip}}:{{dst_path}}
# ---- 接收侧校验 ----
sha256sum {{dst_path}}

entries.rollback:
# 守卫：备份不存在则中止，禁止盲恢复
ls /etc/login.defs.bak-20261014 || { echo '备份缺失，停止回退，人工核查'; exit 1; }
# 恢复 login.defs 默认策略
cp -a /etc/login.defs.bak-20261014 /etc/login.defs
# 单账户 chage 无文件级回退：先 chage -l 记录原值，再手工恢复
chage -l {{username}}

entries.commands:
# ===== 用户口令修改与锁定排查（passwd，Linux 通用）=====
# ---- 0. 现状：账户状态（P=有效口令 / L=锁定 / NP=无口令）----
passwd -S {{username}}
# ---- 1. 交互式改口令（输两遍新口令不回显；root 可代改他人）----
passwd {{username}}
# ---- 复核：状态应为 P ----
passwd -S {{username}}

entries.rollback:
# 回退：口令变更无自动回退——再次执行 passwd 改回原口令（原口令按变更记录）
passwd {{username}}
# 若误锁定账户：解锁
passwd -u {{username}}

# 守卫：备份不存在则中止，禁止盲恢复
ls {{config_file}}.bak-20261014 || { echo '备份缺失，停止回退，人工核查'; exit 1; }
# 备份在才恢复
cp -a {{config_file}}.bak-20261014 {{config_file}}
# 恢复后按发行版生效：RHEL 系 ifup <接口> / netplan 体系 netplan apply
